#include <cstddef>
#include <initializer_list>
#include <utility>

class IntVector
{
public:
    IntVector() = default;

    IntVector(std::initializer_list<int> values)
    {
        reserve(values.size());
        for (int value : values)
        {
            m_data[m_size++] = value;
        }
    }

    ~IntVector() { delete[] m_data; }

    IntVector(const IntVector& other)
    {
        reserve(other.m_size);
        for (std::size_t i{ 0 }; i < other.m_size; ++i)
        {
            m_data[i] = other.m_data[i];
        }
        m_size = other.m_size;
    }

    IntVector(IntVector&& other) noexcept
        : m_data{ std::exchange(other.m_data, nullptr) }, m_size{ std::exchange(other.m_size, 0) }, m_capacity{ std::exchange(other.m_capacity, 0) }
    {
    }

    IntVector& operator=(IntVector other) noexcept
    {
        std::swap(m_data, other.m_data);
        std::swap(m_size, other.m_size);
        std::swap(m_capacity, other.m_capacity);
        return *this;
    }

    void push_back(int value)
    {
        if (m_size == m_capacity)
        {
            reserve(m_capacity == 0 ? 1 : m_capacity * 2);
        }
        m_data[m_size++] = value;
    }

    void pop_back()
    {
        if (m_size > 0)
        {
            --m_size;
        }
    }

    void reserve(std::size_t n)
    {
        if (n <= m_capacity)
        {
            return;
        }
        int* fresh{ new int[n] };
        for (std::size_t i{ 0 }; i < m_size; ++i)
        {
            fresh[i] = m_data[i];
        }
        delete[] m_data;
        m_data = fresh;
        m_capacity = n;
    }

    int& operator[](std::size_t i) { return m_data[i]; }
    const int& operator[](std::size_t i) const { return m_data[i]; }
    std::size_t size() const { return m_size; }
    std::size_t capacity() const { return m_capacity; }
    bool empty() const { return m_size == 0; }

    int* begin() { return m_data; }
    int* end() { return m_data + m_size; }
    const int* begin() const { return m_data; }
    const int* end() const { return m_data + m_size; }

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
    std::size_t m_capacity{ 0 };
};

unitTests:
static_assert(std::is_nothrow_move_constructible_v<IntVector>, "the move constructor should be noexcept");

TEST("starts empty without allocating") { const IntVector v{}; CHECK(v.empty()); CHECK_EQ(v.size(), 0u); CHECK_EQ(v.capacity(), 0u); CHECK(v.begin() == v.end()); }
TEST("initializer list") { const IntVector v{ 4, 5, 6 }; CHECK_EQ(v.size(), 3u); CHECK_EQ(v.capacity(), 3u); CHECK_EQ(v[0], 4); CHECK_EQ(v[2], 6); }
TEST("push_back doubles the capacity") { IntVector v{}; std::string caps; for (int i{ 0 }; i < 9; ++i) { v.push_back(i); caps += std::to_string(v.capacity()) + ' '; } CHECK_EQ(caps, "1 2 4 4 8 8 8 8 16 "); CHECK_EQ(v.size(), 9u); CHECK_EQ(v[8], 8); CHECK_EQ(v[0], 0); }
TEST("pop_back") { IntVector v{ 1, 2, 3 }; v.pop_back(); CHECK_EQ(v.size(), 2u); CHECK_EQ(v.capacity(), 3u); v.pop_back(); v.pop_back(); v.pop_back(); CHECK(v.empty()); }
TEST("reserve") { IntVector v{ 1, 2 }; v.reserve(10); CHECK_EQ(v.capacity(), 10u); CHECK_EQ(v.size(), 2u); CHECK_EQ(v[1], 2); v.reserve(3); CHECK_EQ(v.capacity(), 10u); }
TEST("copies are deep") { IntVector a{ 1, 2, 3 }; IntVector b{ a }; b[0] = 99; CHECK_EQ(a[0], 1); IntVector c{}; c = a; c.push_back(4); CHECK_EQ(a.size(), 3u); CHECK_EQ(c.size(), 4u); }
TEST("moves steal the storage") { IntVector a{ 1, 2, 3 }; const int* p{ a.begin() }; IntVector b{ std::move(a) }; CHECK(b.begin() == p); CHECK(a.empty()); CHECK_EQ(a.capacity(), 0u); IntVector c{}; c = std::move(b); CHECK(c.begin() == p); CHECK_EQ(c.size(), 3u); }
TEST("range-for") { IntVector v{ 1, 2, 3 }; for (int& x : v) x *= 2; int total{ 0 }; for (int x : v) total += x; CHECK_EQ(total, 12); }
TEST("no leaks") { CHECK_NO_LEAK(IntVector a{}; for (int i{ 0 }; i < 1000; ++i) a.push_back(i); IntVector b{ a }; IntVector c{ std::move(a) }; b = c; c = IntVector{ 1, 2 }; a.push_back(1)); }

